---@class ForgingComponent
local ForgingComponent = Class("ForgingComponent", ECSComponent)
function ForgingComponent:__init()
    self.name = "ForgingComponent"
    ------------ 参数表数据 ------------
    self.goodsIdExpend = nil--消耗道具id
    self.goodsIdProduced = nil--产出道具id
    self.cycleTimes = nil--单周期时间（单位s）
    self.cycleExpendNum = nil--单周期消耗道具数量
    self.cycleProducedNum = nil--单周期产出道具数量
    self.goodsIdExtraProduced = nil--产出活动道具id
    self.cycleExtraProducedNum = nil--单周期产出活动道具数量
    self.cycleLimit = nil --周期队列上限
    ------------ 参数表数据 ------------

    self.blockNumFinish = 0--生产进度小方块的数量（完成）
    self.blockNumDoing = 0--生产进度小方块的数量（进行中）
    self.blockNumWait = 0--生产进度小方块的数量（等待中）
    self.timer = nil
    self.curForgingGrade = 0--玩家当前的制造等级


    ------------ 服务端数据 ------------
    self.questId = nil--最新通关的关卡id
    self.currentMakeNum = nil--可领取数量
    self.currentOverMakeTimes = nil--完成的次数
    self.timeLeft = nil--进入界面时时请求的总倒计时
    self.makeCallNum = nil--普通总产出（分子）
    self.activityCallNum = nil--活动总产出（分子）

    self.closeTimeLeft = nil--活动关闭剩余时间
    self.rewards = {}--上周未领取的奖励
    ------------ 服务端数据 ------------

end

