function ForgingComponent:InitialDojo(jsonData)
    self.questId = checkNumber(jsonData.questId)
    self.currentOverMakeTimes = checkNumber(jsonData.currentOverMakeTimes)--字段名改为currentOverMakeTimes
    self.timeLeft = checkNumber(jsonData.timeLeft)
    self.makeCallNum = checkNumber(jsonData.makeCallNum)
    self.activityCallNum = checkNumber(jsonData.activityCallNum)
    self.closeTimeLeft = checkNumber(jsonData.closeTimeLeft)
    self.rewards = checkTable(jsonData.rewards)
end

function ForgingComponent:InitialCheckInDojo(jsonData)
    self.currentOverMakeTimes = checkNumber(jsonData.currentOverMakeTimes)
    self.timeLeft = checkNumber(jsonData.timeLeft)
    self:SetArgVo()
    self:CalculateCycleBlockData(self.timeLeft)
end

---制造参数表中的参数获取
function ForgingComponent:SetArgVo()
    local argVo = CfUtils.GetWholeVo(AutoIds.IdSetting1820, "ForgingArgVo")
    for k, v in pairs(argVo) do
        if checkNumber(v.id) == 1 then
            self.goodsIdExpend = checkNumber(v.num)
        elseif checkNumber(v.id) == 2 then
            self.goodsIdProduced = checkNumber(v.num)
        elseif checkNumber(v.id) == 3 then
            self.cycleTimes = checkNumber(v.num)
        elseif checkNumber(v.id) == 4 then
            self.cycleExpendNum = checkNumber(v.num)
        elseif checkNumber(v.id) == 5 then
            self.cycleProducedNum = checkNumber(v.num)
        elseif checkNumber(v.id) == 9 then
            self.goodsIdExtraProduced = checkNumber(v.num)
        elseif checkNumber(v.id) == 10 then
            self.cycleExtraProducedNum = checkNumber(v.num)
        elseif checkNumber(v.id) == 11 then
            self.cycleLimit = checkNumber(v.num)
        end
    end
end



function ForgingComponent:CalculateCycleBlockData(countDown)
    self.blockNumFinish = self.currentOverMakeTimes--self.currentMakeNum / self.cycleProducedNum
    local integer = math.floor(countDown / self.cycleTimes)
    local remainder = math.fmod(countDown, self.cycleTimes)
    --printInfo("remainder---11---->>"..remainder)
    if remainder == 0 and integer >= 1 then
        remainder = self.cycleTimes
        integer = integer - 1
    end
    --printInfo("remainder----22--->>"..remainder)
    self.blockNumDoing = remainder > 0 and 1 or 0
    self.blockNumWait = integer
    --printInfo("blockNumDoing-------->>"..self.blockNumDoing)
    --printInfo("blockNumWait-------->>"..self.blockNumWait)
    --printInfo("blockNumFinish-------->>"..self.blockNumFinish)
    if remainder > 0 then
        self:StartLeftSecond(remainder)
    end
end

function ForgingComponent:StartLeftSecond(countDown)
    self:StopTimer()
    --printInfo("countDown---->>"..countDown)
    countDown = checkNumber(countDown)
    self.timer = CDTimerModule:AddCD(1, function (count, id)
        --printInfo("count--->>"..ForgingComponent.timeLeft)
        self.timeLeft = self.timeLeft - 1
        if count == 0 then
            self:OneCycleFinish()
        end
    end, countDown, false, true, true)
end

function ForgingComponent:OneCycleFinish()
    --数据更新
    self.currentOverMakeTimes = self.currentOverMakeTimes + 1
    --self.currentMakeNum = self.currentMakeNum + self.cycleProducedNum
    self:CalculateCycleBlockData(self.timeLeft)
end

function ForgingComponent:StopTimer()
    if not isNull(self.timer) then
        CDTimerModule:RemoveCD(self.timer)
        self.timer = nil
    end
end

function ForgingComponent:GetHomeStatus()
    local status = 3

    --if self.currentMakeNum > 0 then
    if self.currentOverMakeTimes > 0 then
        status = 2
    elseif self.timeLeft > 0 then
        status = 1
    end
    --printInfo("status====>>"..status)
    return status
end

---@param passedQuestId number 最新通关的关卡id
function ForgingComponent:SetPlayerPrefs(passedQuestId)
    passedQuestId = checkNumber(passedQuestId)
    local playerId = GameUtils.GetPlayerId()
    local PlayerPrefsUtility = CS.Engine.Tools.PlayerPrefsUtility
    local key = "ForgingComponentUnlockCondition"..playerId
    PlayerPrefsUtility.SetEncryptedInt(key, passedQuestId)
end

---@return number 历史最高通关的关卡id
function ForgingComponent:GetPlayerPrefs()
    local playerId = GameUtils.GetPlayerId()
    local PlayerPrefsUtility = CS.Engine.Tools.PlayerPrefsUtility
    local key = "ForgingComponentUnlockCondition"..playerId
    local passedQuestId = PlayerPrefsUtility.GetEncryptedInt(key, 0)
    --if isNull(passedQuestId) then
    --    passedQuestId = 0
    --end
    return passedQuestId
end

function ForgingComponent:TryOpenUpgradePopup(passedQuestId)
    if isNull(passedQuestId) then
        return
    end

    local passedQuestData = QuestConfMgr:GetInstance():GetQuestVoById(passedQuestId)
    local forgingGradeData = CfUtils.GetCfVo(AutoIds.IdSetting1821, "ForgingGradeVo", passedQuestData.regionLevel)
    self.curForgingGrade = forgingGradeData.id
    --local passedQuestId = self:GetPlayerPrefs()
    if passedQuestId > self.questId then
        UIModule.OpenDialog(
                {
                    id = Constants.UITypeIds.ForgingUpgradePopup,
                    parameters = {
                        --passedQuestId = self.questId,
                        passedQuestId = passedQuestId,
                    }
                }
        )
        --self:SetPlayerPrefs(self.questId)
    end
end

return ForgingComponent